.logo:hover { color: #FFFFFF; }
.logo span { color: var(--accent-on-ink); }

header nav {
    flex: 0 1 auto;
    min-width: 0;
    margin-left: auto;
    padding: var(--s3) 0;
    display: flex;
    align-items: center;
    gap: var(--s1);
    overflow-x: auto;
    overscroll-behavior-x: contain;
    scroll-snap-type: x proximity;
    scrollbar-width: none;
    -ms-overflow-style: none;
}

header nav::-webkit-scrollbar { display: none; }

header nav > * {
    flex: none;
    scroll-snap-align: end;
}

header nav a {
    padding: 9px 13px;
    border-radius: var(--r-sm);
    color: var(--text-on-ink-2);
    font-size: var(--fs-sm);
    font-weight: 600;
    text-decoration: none;
    white-space: nowrap;
    transition: color var(--t-fast), background-color var(--t-fast);
}

header nav a:hover {
    color: #FFFFFF;
    background-color: rgba(255, 255, 255, .07);
}

header nav a.active {
    color: var(--accent-on-ink);
    background-color: rgba(224, 164, 88, .12);
}

header nav a.btn-nav {
    margin-left: var(--s2);
    background-color: var(--accent);
    color: #FFFFFF;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, .12);
}

header nav a.btn-nav:hover,
header nav a.btn-nav.active {
    background-color: var(--accent-hover);
    color: #FFFFFF;
}

.lang-select {
    flex: none;
    margin-left: var(--s2);
    padding: 8px 10px;
    background-color: rgba(255, 255, 255, .06);
    color: #FFFFFF;
    border: 1px solid rgba(255, 255, 255, .18);
    border-radius: var(--r-sm);
    font-family: var(--font-sans);
    font-size: var(--fs-sm);
    font-weight: 600;
    line-height: 1;
    cursor: pointer;
    transition: border-color var(--t-fast), background-color var(--t-fast);
}

--- btn-card ---
    color: var(--ink);
    border: 1px solid var(--border-strong);
}

.btn-secondary:hover {
    background-color: rgba(15, 42, 46, .04);
    border-color: var(--ink);
    color: var(--ink);
}

.btn-card {
    min-height: 38px;
    padding: 0 var(--s4);
    background-color: var(--accent);
    color: #FFFFFF;
    border: 1px solid var(--accent);
}

.btn-card:hover {
    background-color: var(--accent-hover);
    border-color: var(--accent-hover);
--- tab-btn ---
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: var(--s2);
    margin-bottom: var(--s7);
}

.tab-btn {
    min-height: 40px;
    padding: 0 var(--s4);
    background-color: var(--surface);
    color: var(--text-2);
    border: 1px solid var(--border);
    border-radius: var(--r-pill);
    font-family: var(--font-sans);
    font-size: var(--fs-sm);
    font-weight: 600;
    line-height: 1;
    cursor: pointer;
    transition: background-color var(--t-fast), color var(--t-fast),
                border-color var(--t-fast);
}

.tab-btn:hover {
    border-color: var(--accent);
    color: var(--accent);
--- modal-close ---
    color: var(--ink);
}

.modal-close {
    position: absolute;
    top: var(--s4);
    right: var(--s4);
    width: 38px;
    height: 38px;
    display: flex;
    align-items: center;
    justify-content: center;
    background-color: var(--canvas-2);
    color: var(--ink);
    border: 1px solid var(--border);
    border-radius: 50%;
    font-size: 1.4rem;
    line-height: 1;
    cursor: pointer;
    transition: background-color var(--t-fast), color var(--t-fast),
                border-color var(--t-fast);
